<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {CompanyProvidersClient} from './providers-client';
 export let companyId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();let client:CompanyProvidersClient|null=null,available=false,consent=false,busy=false,error='',count=0,alive=true;
 onMount(()=>{client=new CompanyProvidersClient(companyId,()=>localStorage.token||'');if(accessSignal?.aborted)return;void client.companyAccount().then(d=>{if(alive&&!accessSignal.aborted){available=d.available;count=d.models.length;}}).catch(()=>{});});
 onDestroy(()=>{alive=false;client?.close();});
 async function share(){if(!client||!consent||busy||accessSignal.aborted)return;busy=true;error='';try{await client.shareCompanyAccount();if(alive&&!accessSignal.aborted){consent=false;dispatch('connected');}}catch(e){if(alive)error=(e as Error).message;}finally{if(alive)busy=false;}}
</script>
{#if available}<section class="account-connection" aria-label="Connect OpenAI for your company"><strong>Use your connected OpenAI account for this company</strong><p>Your account has {count} registered models. Create a company connection, then choose a provider and model independently for each bot.</p><label><input type="checkbox" bind:checked={consent} disabled={busy}/><span>I authorize this company’s permitted bots to use my connected OpenAI account. This connection remains available until revoked or the account is disconnected.</span></label><button type="button" disabled={!consent||busy} on:click={share}>{busy?'Connecting…':'Connect OpenAI for this company'}</button>{#if error}<p class="error" role="alert">{error}</p>{/if}</section>{/if}
<style>.account-connection{padding:18px;border:1px solid #cdddfb;background:#f3f7ff;border-radius:12px;margin:20px 0;color:#17233b}.account-connection strong{font-size:13px}.account-connection p{font-size:12px;color:#526780;line-height:1.6;margin:9px 0}.account-connection label{display:flex;gap:10px;align-items:flex-start;font-size:12px;line-height:1.6;margin:14px 0}.account-connection input{width:16px;height:16px;flex:none;margin-top:2px;accent-color:#2563eb}.account-connection button{background:#2563eb;color:white;border:0;border-radius:8px;padding:10px 14px;font-size:12px;font-weight:600;cursor:pointer}.account-connection button:disabled{opacity:.45;cursor:default}.account-connection button:focus-visible,.account-connection input:focus-visible{outline:2px solid #2563eb;outline-offset:3px}.account-connection .error{color:#be123c}</style>
